<?php require 'inc/bootstrap.php'; need('admin'); $title = 'Settings';
if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (($_POST['action'] ?? '') === 'mail_test') {
    $to = trim($_POST['test_to']); if (!valid_email($to)) flash('Enter a valid email address to send the test to.', 'danger');
    elseif (!mail_enabled()) flash('Save your email settings first.', 'danger');
    else { $ok = mail_deliver($to, 'Test email from '.$cfg['app_name'], mail_wrap('It works', '<p>This is a test message. Your email settings are working.</p>'), "This is a test message. Your email settings are working.", $err); flash($ok ? "Test email sent to $to. Check the inbox and spam folder." : 'Test failed: '.$err, $ok ? 'success' : 'danger'); }
  }
  elseif (($_POST['action'] ?? '') === 'cron_key') { set_setting('cron_key', bin2hex(random_bytes(16))); audit('cron_key_new'); flash('New scheduled-task address created. Update your cron job.'); }
  elseif (($_POST['action'] ?? '') === 'digest_me') { $mu = q("SELECT * FROM users WHERE id=?", [me()['id']])->fetch(); if (!mail_enabled()) flash('Save your email settings first.', 'danger'); elseif (!valid_email($mu['email'] ?? '')) flash('Add your email address on the Account page first.', 'danger'); else { if (!digest_send($mu, '[Preview] ')) flash('Nothing needs attention right now, so no summary was sent.', 'info'); else flash('A summary was queued for '.$mu['email'].'.', 'success'); } }
  elseif (($_POST['action'] ?? '') === 'clear_lockouts') { q("DELETE FROM login_attempts"); audit('lockouts_cleared'); flash('All login lockouts cleared.'); }
  else {
    $clamp = fn($v, $lo, $hi) => max($lo, min($hi, (int)$v));
    $new = ['org_name'=>trim($_POST['org_name']) ?: 'GPIMS', 'found_phone'=>trim($_POST['found_phone']), 'loan_terms'=>mb_substr(trim($_POST['loan_terms'] ?? ''), 0, 1000), 'maint_warn_days'=>max(0, min(90, (int)($_POST['maint_warn_days'] ?? 7))),
            'session_timeout_min'=>$clamp($_POST['session_timeout_min'], 0, 1440), 'max_login_attempts'=>$clamp($_POST['max_login_attempts'], 0, 50), 'lockout_minutes'=>$clamp($_POST['lockout_minutes'], 1, 1440), 'expiry_warn_days'=>$clamp($_POST['expiry_warn_days'], 0, 365), 'passkeys_enabled'=>isset($_POST['passkeys_enabled']) ? '1' : '0', 'lookup_enabled'=>isset($_POST['lookup_enabled']) ? '1' : '0', 'trash_days'=>(string)$clamp($_POST['trash_days'] ?? 30, 1, 365), 'mail_method'=>in_array($_POST['mail_method'] ?? '', ['off','smtp','php'], true) ? $_POST['mail_method'] : 'off', 'mail_from_name'=>trim($_POST['mail_from_name'] ?? ''), 'mail_from_email'=>valid_email(trim($_POST['mail_from_email'] ?? '')) ? trim($_POST['mail_from_email']) : '', 'smtp_host'=>trim($_POST['smtp_host'] ?? ''), 'smtp_port'=>(string)max(1, min(65535, (int)($_POST['smtp_port'] ?? 587))), 'smtp_secure'=>in_array($_POST['smtp_secure'] ?? '', ['tls','ssl','none'], true) ? $_POST['smtp_secure'] : 'tls', 'smtp_user'=>trim($_POST['smtp_user'] ?? ''), 'site_url'=>rtrim(trim($_POST['site_url'] ?? ''), '/'), 'digest_hour'=>(string)$clamp($_POST['digest_hour'] ?? 7, 0, 23), 'timezone'=>in_array($_POST['timezone'] ?? '', DateTimeZone::listIdentifiers(), true) ? $_POST['timezone'] : ''];
    if (($_POST['smtp_pass'] ?? '') !== '') { set_setting('smtp_pass_enc', mail_enc($_POST['smtp_pass'])); }
    $changed = [];
    foreach ($new as $k => $v) { if ((string)setting($k, '') !== (string)$v) { set_setting($k, (string)$v); $changed[] = $k; } }
    if ($changed) { audit('settings_update', implode(', ', $changed)); flash('Settings saved.'); } else flash('No changes.', 'info');
  }
  redirect('settings.php');
}
$recent = (int)q("SELECT COUNT(*) FROM login_attempts WHERE created_at > (NOW() - INTERVAL 1 DAY)")->fetchColumn();
include 'inc/header.php'; ?>
